const crypto = require('crypto');
function invalid(error) { return [{ json: { ok: false, valid: false, error } }]; }
const BOT_TOKEN = String($vars.TELEGRAM_BOT_TOKEN ?? $env.TELEGRAM_BOT_TOKEN ?? '').trim();
if (!BOT_TOKEN) throw new Error('Falta configurar TELEGRAM_BOT_TOKEN en n8n.');
const input = $input.first()?.json ?? {};
let body = input.body ?? input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { return invalid('invalid_json'); } }
const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
const itemId = typeof body.item_id === 'string' ? body.item_id.trim() : '';
const action = typeof body.action === 'string' ? body.action.trim() : 'complete';
const reservationDays = Number(body.reservation_days ?? 1);
const renewalDays = Number(body.renewal_days ?? 14);
if (!initData) return invalid('telegram_init_data_missing');
if (!itemId || itemId.length > 120) return invalid('item_id_invalid');
if (!['complete', 'reopen', 'hide', 'reserve', 'release', 'renew'].includes(action)) return invalid('action_invalid');
if (action === 'reserve' && (!Number.isInteger(reservationDays) || reservationDays < 1 || reservationDays > 30)) return invalid('reservation_days_invalid');
if (action === 'renew' && ![7, 14, 30].includes(renewalDays)) return invalid('renewal_days_invalid');
const fields = {};
try {
  for (const part of String(initData).split('&')) {
    const separator = part.indexOf('=');
    if (separator < 0) continue;
    const key = decodeURIComponent(part.slice(0, separator).replaceAll('+', ' '));
    fields[key] = decodeURIComponent(part.slice(separator + 1).replaceAll('+', ' '));
  }
} catch { return invalid('telegram_init_data_malformed'); }
const receivedHash = fields.hash ?? '';
const authDate = Number(fields.auth_date);
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) return invalid('telegram_init_data_invalid');
const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 86400) return invalid('telegram_init_data_expired');
const dataCheckString = Object.keys(fields).filter((key) => key !== 'hash').sort().map((key) => key + '=' + fields[key]).join(String.fromCharCode(10));
const secretKey = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) return invalid('telegram_identity_invalid');
let user;
try { user = JSON.parse(fields.user ?? '{}'); } catch { return invalid('telegram_user_invalid'); }
if (!user || !Number.isSafeInteger(user.id)) return invalid('telegram_user_invalid');
return [{ json: {
  ok: true,
  valid: true,
  item_id: itemId,
  action,
  reservation_days: action === 'reserve' ? reservationDays : null,
  renewal_days: action === 'renew' ? renewalDays : null,
  telegram_id: String(user.id),
} }];

const auth = $('Validate Telegram initData').first()?.json ?? {};
const rows = $input.all();
function invalid(error) { return [{ json: { ok: false, valid: false, error } }]; }
if (auth.valid !== true) return [{ json: auth }];
const found = rows.map(({ json }) => ({ json, fields: json.fields ?? json })).find(({ fields }) => String(fields.public_id ?? fields['item-id'] ?? '') === String(auth.item_id));
if (!found) return invalid('item_not_found');
const fields = found.fields;
if (String(fields.owner_telegram_id ?? '') !== String(auth.telegram_id)) return invalid('not_owner');
const action = ['complete', 'reopen', 'hide', 'reserve', 'release', 'renew'].includes(auth.action) ? auth.action : 'complete';
const reservationDays = Number(auth.reservation_days ?? 1);
const renewalDays = Number(auth.renewal_days ?? 14);
const storedStatus = String(fields.status ?? '').toLowerCase();
const now = Date.now();
const expiresTimestamp = fields.expires_at ? Date.parse(String(fields.expires_at).replace(' ', 'T')) : NaN;
const reservationExpiresTimestamp = fields.reservation_expires_at ? Date.parse(String(fields.reservation_expires_at).replace(' ', 'T')) : NaN;
const reservationExpired = storedStatus === 'reserved' && Number.isFinite(reservationExpiresTimestamp) && reservationExpiresTimestamp <= now;
const publicationExpired = storedStatus === 'expired' || (['available', 'reserved'].includes(storedStatus) && Number.isFinite(expiresTimestamp) && expiresTimestamp <= now);
const currentStatus = publicationExpired ? 'expired' : reservationExpired ? 'available' : storedStatus;
const renewalCount = Math.max(0, Math.trunc(Number(fields.renewal_count ?? 0)));
const hasInterest = [fields.favorite_count, fields.interest_count, fields.contact_attempt_count].some((value) => Number(value ?? 0) > 0);
if (action === 'complete' && !['available', 'reserved'].includes(currentStatus)) return invalid(currentStatus === 'completed' ? 'item_already_completed' : 'item_not_available');
if (action === 'reopen' && currentStatus !== 'completed') return invalid('item_not_completed');
if (action === 'reserve' && currentStatus !== 'available') return invalid('item_not_available');
if (action === 'release' && currentStatus !== 'reserved') return invalid('item_not_reserved');
if (action === 'renew' && currentStatus !== 'expired') return invalid('item_not_expired');
if (action === 'renew' && renewalCount >= 2) return invalid('renewal_limit_reached');
if (action === 'renew' && renewalCount === 1 && !hasInterest) return invalid('renewal_interest_required');
if (action === 'hide' && !['available', 'reserved', 'completed', 'expired'].includes(currentStatus)) return invalid(currentStatus === 'hidden' ? 'item_already_hidden' : 'item_not_available');
const rowId = fields.Id ?? found.json.Id ?? found.json.id ?? null;
if (rowId === null || rowId === undefined || rowId === '') return invalid('nocodb_row_id_missing');
const nextStatus = action === 'hide' ? 'hidden' : ['reopen', 'release', 'renew'].includes(action) ? 'available' : action === 'reserve' ? 'reserved' : 'completed';
const completedAt = action === 'hide'
  ? currentStatus === 'completed' ? fields.completed_at ?? null : null
  : ['reopen', 'release', 'reserve', 'renew'].includes(action) ? null : new Date().toISOString();
const reservedAt = nextStatus === 'reserved' ? new Date().toISOString() : null;
const nextReservationExpiresAt = nextStatus === 'reserved' ? new Date(now + reservationDays * 24 * 60 * 60 * 1000).toISOString() : null;
const nextExpiresAt = action === 'renew' ? new Date(now + renewalDays * 24 * 60 * 60 * 1000).toISOString() : fields.expires_at ?? null;
const nextRenewalCount = action === 'renew' ? renewalCount + 1 : renewalCount;
return [{ json: {
  ok: true,
  valid: true,
  Id: rowId,
  item_id: auth.item_id,
  action,
  status: nextStatus,
  expires_at: nextExpiresAt,
  renewal_count: nextRenewalCount,
  completed_at: completedAt,
  reserved_at: reservedAt,
  reservation_expires_at: nextReservationExpiresAt,
  reservation_days: nextStatus === 'reserved' ? reservationDays : null,
  renewal_days: action === 'renew' ? renewalDays : null,
  title: fields.title ?? '',
} }];
